import {createMaterialReadingUI} from './class-material-reading-ui.mjs';
import {createMaterialControls} from './class-material-controls.mjs';
export function createClassMaterialsUI({e,ui,link,filesView,fileInput}){
 const reading=createMaterialReadingUI({e});
 const controls=createMaterialControls({e,fileInput});
 function page(room,staff,params,classes=[]){
  if(staff&&room.studentMaterialReading)return reading.studentReport(room.studentMaterialReading,link);
  if(staff&&params.get('materialReport')==='1'&&room.materialReadingOverview)return reading.overview(room.materialReadingOverview,link);
  const id=room.class.id,all=room.resources||[],archived=staff&&params.get('materialStatus')==='archived',topic=params.get('materialTopic')||'',search=params.get('materialSearch')||'',focused=params.get('material')||'',topics=[...new Set(all.map(r=>r.topic||'Class materials'))].sort(),rows=all.filter(r=>(focused?r.id===focused:!!r.archived===archived)&&(!topic||(r.topic||'Class materials')===topic)&&(!search||[r.title,r.body,r.topic,...(r.files||[]).map(f=>f.name)].join(' ').toLocaleLowerCase().includes(search.toLocaleLowerCase()))).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))||a.id.localeCompare(b.id));
  const limit=6,requested=Number(params.get('materialOffset')||0),offset=rows.length?Math.min(Number.isSafeInteger(requested)&&requested>=0?Math.floor(requested/limit)*limit:0,Math.floor((rows.length-1)/limit)*limit):0,visible=rows.slice(offset,offset+limit),paging={class:id,tab:'apps',...(archived?{materialStatus:'archived'}:{}),...(topic?{materialTopic:topic}:{}),...(search?{materialSearch:search}:{})};
  return '<div class="learning-section-title"><h2>Class materials</h2><span>'+all.filter(r=>!r.archived).length+' available'+(staff?' · '+all.filter(r=>r.archived).length+' archived':'')+'</span></div><p>Read class guides and download documents here.</p>'+(staff?'<p>'+link('Available materials',{class:id,tab:'apps'})+' · '+link('Archived materials',{class:id,tab:'apps',materialStatus:'archived'})+' · '+link('Class reading overview',{class:id,tab:'apps',materialReport:'1'})+'</p>':'')+''+(staff?'<details class="vle-panel"><summary>＋ Add class material</summary><form data-vle="resource"><input type="hidden" name="classId" value="'+e(id)+'"><input type="hidden" name="provider" value="Class material"><div class="vle-form-grid"><label class="vle-field">Title<input name="title" maxlength="160" required></label><label class="vle-field">Topic<input name="topic" maxlength="100" value="Class materials" list="material-topics"></label></div><datalist id="material-topics">'+topics.map(t=>'<option value="'+e(t)+'"></option>').join('')+'</datalist><label class="vle-field">Description<textarea name="body" maxlength="10000"></textarea></label>'+fileInput()+'<details><summary>Optional web link</summary><label class="vle-field">HTTPS link<input name="url" type="url" placeholder="https://…"></label></details><p class="vle-note">This material will be available to the students in this class. It does not create an assignment or a grade.</p><button type="submit" class="btn primary">Share material</button></form></details>':'')+(focused?'<p>'+link('← All class materials',{class:id,tab:'apps'})+'</p>':'<form id="material-filters" class="community-filters" data-class="'+e(id)+'">'+(staff?'<label>Show<select name="materialStatus" aria-label="Material visibility"><option value="available">Available</option><option value="archived" '+(archived?'selected':'')+'>Archived</option></select></label>':'')+'<label>Topic<select name="materialTopic" aria-label="Material topic"><option value="">All topics</option>'+topics.map(t=>'<option value="'+e(t)+'" '+(t===topic?'selected':'')+'>'+e(t)+'</option>').join('')+'</select></label><label>Find<input name="materialSearch" aria-label="Find class material" maxlength="120" placeholder="Title, description or filename" value="'+e(search)+'"></label><button type="submit" class="btn">Find materials</button>'+link('Clear filters',{class:id,tab:'apps'})+'</form>')+'<p>'+rows.length+' matching '+(rows.length===1?'material':'materials')+'</p><div class="'+(focused?'':'vle-grid')+'">'+visible.map(r=>'<article class="vle-panel material-card"><small>'+e(r.topic||'Class materials')+(r.archived?' · Archived':'')+'</small><h3>'+(focused?e(r.title):link(r.title,{class:id,tab:'apps',material:r.id}))+'</h3>'+(focused?'<p class="vle-prose">'+e(r.body||'')+'</p>'+filesView(r.files)+(r.url?'<p><a href="'+e(r.url)+'" target="_blank" rel="noopener noreferrer">Open '+e(r.provider&&r.provider!=='Class material'?r.provider:'web link')+' ↗</a></p>':''):'<p>'+(r.files?.length?r.files.length+' attached '+(r.files.length===1?'file':'files'):r.url?'Web resource':'Reading material')+'</p>'+link('Open material →',{class:id,tab:'apps',material:r.id}))+'<small>Shared by '+e(r.author||room.class.teacher)+' · '+e(new Date(r.createdAt).toLocaleDateString('en-GB'))+'</small>'+(focused?(staff?reading.teacher(room.materialReaders)+controls(r,classes):reading.student(r)):'')+'</article>').join('')+(!rows.length?'<p class="learning-empty">'+(focused?'This material is unavailable in this class.':search||topic?'No materials match these filters.':'Your teacher has not shared any materials here yet.')+'</p>':'')+'</div><div class="vle-actions">'+(offset?link('← Previous',{...paging,materialOffset:Math.max(0,offset-limit)}):'')+(offset+limit<rows.length?link('Next →',{...paging,materialOffset:offset+limit}):'')+'</div>';
 }
 function bind(root){reading.bind(root);root.querySelector('#material-filters')?.addEventListener('submit',ev=>{ev.preventDefault();const q=new URLSearchParams({class:ev.currentTarget.dataset.class,tab:'apps'});for(const [k,v]of new FormData(ev.currentTarget))if(v)q.set(k,v);const target='#/classroom?'+q;if(location.hash===target)ui.render();else location.hash=target;});}
 return{page,bind};
}

